insert into public.standard (doc_id, strand_id, grade, code, code_type, source_system_id, level, parent_id, text, extra, source_url, display_order, needs_review, last_verified)
values
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 1, $txt$N01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to say the number sequence by: 1s, forward and backward between any two given numbers, 0 to 100; 2s to 20, forward starting at 0; 5s to 100, forward starting at 0, using a hundred chart or a number line; 10s to 100, forward starting at 0, using a hundred chart or a number line$txt$, $txt${"display_code":"Gr1 N01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 1, $txt$N02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to recognize, at a glance, and name the quantity represented by familiar arrangements of one to ten objects or dots.$txt$, $txt${"display_code":"Gr1 N02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 1, $txt$N03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of counting to 20 by indicating that the last number said identifies “how many”; showing that any set has only one count; using the counting-on strategy$txt$, $txt${"display_code":"Gr1 N03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 1, $txt$N04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to represent and partition numbers to 20.$txt$, $txt${"display_code":"Gr1 N04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 1, $txt$N05$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to compare sets containing up to 20 objects to solve problems using referents and one-to-one correspondence.$txt$, $txt${"display_code":"Gr1 N05"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 1, $txt$N06$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to estimate quantities to 20 by using referents.$txt$, $txt${"display_code":"Gr1 N06"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 1, $txt$N07$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of conservation of number for up to 20 objects.$txt$, $txt${"display_code":"Gr1 N07"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 1, $txt$N08$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to identify the number, up to 20, that is one more, two more, one less, and two less than a given number.$txt$, $txt${"display_code":"Gr1 N08"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 1, $txt$N09$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of the addition of two one-digit numbers and the corresponding subtraction, concretely, pictorially, and symbolically, in join, separate, and part-part-whole situations.$txt$, $txt${"display_code":"Gr1 N09"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 1, $txt$N10$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to use and describe strategies to determine sums and differences using manipulatives and visual aids. Strategies include: counting on or counting back; one more or one less; making ten; doubles$txt$, $txt${"display_code":"Gr1 N10"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 1, $txt$PR01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of repeating patterns (two to four elements) by identifying, describing, reproducing, extending, and creating patterns using manipulatives, diagrams, sounds, and actions.$txt$, $txt${"display_code":"Gr1 PR01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 1, $txt$PR03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to describe equality as a balance and inequality as an imbalance, concretely and pictorially (0 to 20).$txt$, $txt${"display_code":"Gr1 PR03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 1, $txt$PR04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to record equalities using the equal symbol.$txt$, $txt${"display_code":"Gr1 PR04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 1, $txt$M01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of measurement as a process of comparing by: identifying attributes that can be compared; ordering objects; making statements of comparison; filling, covering, or matching$txt$, $txt${"display_code":"Gr1 M01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 14, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 1, $txt$G01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to sort 3-D objects and 2-D shapes using one attribute and explain the sorting rule.$txt$, $txt${"display_code":"Gr1 G01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 15, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 1, $txt$G02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to replicate composite 2-D shapes and 3-D objects.$txt$, $txt${"display_code":"Gr1 G02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 16, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 1, $txt$G03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to identify 2-D shapes in 3-D objects.$txt$, $txt${"display_code":"Gr1 G03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%201%20Outcomes%20%282022%29.pdf$txt$, 17, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 2, $txt$N01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to say the number sequence by 1s, forward and backward, starting from any point to 200; 2s, forward and backward, starting from any point to 100; 5s and 10s, forward and backward, using starting points that are multiples of 5 and 10 respectively to 100; 10s, starting from any point, to 100$txt$, $txt${"display_code":"Gr2 N01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 2, $txt$N02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate if a number (up to 100) is even or odd.$txt$, $txt${"display_code":"Gr2 N02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 2, $txt$N04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to represent and partition numbers to 100.$txt$, $txt${"display_code":"Gr2 N04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 2, $txt$N05$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to compare and order numbers up to 100.$txt$, $txt${"display_code":"Gr2 N05"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 2, $txt$N06$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to estimate quantities to 100 by using referents.$txt$, $txt${"display_code":"Gr2 N06"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 2, $txt$N07$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to illustrate, concretely and pictorially, the meaning of place value for numerals to 100.$txt$, $txt${"display_code":"Gr2 N07"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 2, $txt$N08$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate and explain the effect of adding zero to or subtracting zero from any number.$txt$, $txt${"display_code":"Gr2 N08"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 2, $txt$N09$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of addition (limited to 1-and 2-digit numerals) with answers to 100 and the corresponding subtraction by: using personal strategies for adding and subtracting with and without the support of manipulates; creating and solving problems that involve addition and subtraction; explaining and demonstrating that the order in which numbers are added does not affect the sum; explaining and demonstrating that the order in which numbers are subtracted matters when finding a difference$txt$, $txt${"display_code":"Gr2 N09"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 2, $txt$N10$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to apply mental mathematics strategies to quickly recall basic addition facts to 18 and determine related subtraction facts.$txt$, $txt${"display_code":"Gr2 N10"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 2, $txt$PR01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of repeating patterns (three to five elements) by describing, extending, comparing, and creating patterns using manipulatives, diagrams, sounds, and actions.$txt$, $txt${"display_code":"Gr2 PR01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 2, $txt$PR02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of increasing patterns by describing, extending, and creating numerical patterns (numbers to 100) and non-numerical patterns using manipulatives, diagrams, sounds, and actions.$txt$, $txt${"display_code":"Gr2 PR02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 2, $txt$PR03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate and explain the meaning of equality and inequality by using manipulatives and diagrams (0 to 100).$txt$, $txt${"display_code":"Gr2 PR03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 2, $txt$PR04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to record equalities and inequalities symbolically, using the equal symbol or not equal symbol.$txt$, $txt${"display_code":"Gr2 PR04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 2, $txt$M01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of the calendar and the relationships among days, weeks, months, and years.$txt$, $txt${"display_code":"Gr2 M01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 14, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 2, $txt$M02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to relate the size of a unit of measure to the number of units (limited to non-standard units) used to measure length and mass.$txt$, $txt${"display_code":"Gr2 M02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 15, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 2, $txt$M03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to compare and order objects by length, height, and mass using non-standard units and make statements of comparison.$txt$, $txt${"display_code":"Gr2 M03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 16, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 2, $txt$M04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to measure length to the nearest non-standard unit by using multiple copies of a unit.$txt$, $txt${"display_code":"Gr2 M04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 17, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 2, $txt$G01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to sort 2-D shapes and 3-D objects using two attributes and explain the sorting rule.$txt$, $txt${"display_code":"Gr2 G01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 18, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 2, $txt$G02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to recognize, name, describe, compare, and build 3-D objects, including cubes and other prisms, spheres, cones, cylinders, and pyramids.$txt$, $txt${"display_code":"Gr2 G02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 19, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 2, $txt$G03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to recognize, name, describe, compare and build 2-D shapes, including triangles, squares, rectangles, and circles.$txt$, $txt${"display_code":"Gr2 G03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 20, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 2, $txt$G04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to identify 2-D shapes as part of 3-D objects in the environment.$txt$, $txt${"display_code":"Gr2 G04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 21, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$SP$txt$), 2, $txt$SP01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to gather and record data about self and others to answer questions.$txt$, $txt${"display_code":"Gr2 SP01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 22, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$SP$txt$), 2, $txt$SP02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to construct and interpret concrete graphs and pictographs to solve problems.$txt$, $txt${"display_code":"Gr2 SP02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%202%20Outcomes%20%282022%29.pdf$txt$, 23, false, $txt$2026-10-17$txt$::date);
insert into public.standard (doc_id, strand_id, grade, code, code_type, source_system_id, level, parent_id, text, extra, source_url, display_order, needs_review, last_verified)
values
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to say the number sequence forward and backward by: 1s through transitions to 1000; 2s, 5s, 10s, or 100s, using any starting point to 1000; 3s, using starting points that are multiples of 3 up to 100; 4s, using starting points that are multiples of 4 up to 100; 25s, using starting points that are multiples of 25 up to 200.$txt$, $txt${"display_code":"Gr3 N01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to represent and partition numbers to 1000.$txt$, $txt${"display_code":"Gr3 N02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to compare and order numbers up to 1000.$txt$, $txt${"display_code":"Gr3 N03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to estimate quantities less than 1000 using referents.$txt$, $txt${"display_code":"Gr3 N04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N05$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to illustrate, concretely and pictorially, the meaning of place value for numerals to 1000.$txt$, $txt${"display_code":"Gr3 N05"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N06$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to describe and apply mental mathematics strategies for adding two 2-digit numerals.$txt$, $txt${"display_code":"Gr3 N06"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N07$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to describe and apply mental mathematics strategies for subtracting two 2-digit numerals.$txt$, $txt${"display_code":"Gr3 N07"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N08$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to apply estimation strategies to predict sums and differences of 1-, 2-, and 3-digit numerals in a problem-solving context.$txt$, $txt${"display_code":"Gr3 N08"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N09$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of addition and subtraction of numbers (limited to 1-, 2-, and 3-digit numerals) with answers to 1000 by: using personal strategies for adding and subtracting with and without the support of manipulatives; creating and solving problems in context that involve addition and subtraction of numbers concretely, pictorially, and symbolically$txt$, $txt${"display_code":"Gr3 N09"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N10$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to apply mental mathematics strategies and number properties to develop quick recall of basic addition facts to 18 and related basic subtraction facts.$txt$, $txt${"display_code":"Gr3 N10"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N11$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of multiplication to 5 × 5 by representing and explaining multiplication using equal grouping and arrays; creating and solving problems in context that involves multiplication; modelling multiplication using concrete and visual representations and recording the process symbolically; relating multiplication to repeated addition; relating multiplication to division$txt$, $txt${"display_code":"Gr3 N11"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N12$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of division by representing and explaining division using equal sharing and equal grouping; creating and solving problems in context that involve equal sharing and equal grouping; modelling equal sharing and equal grouping using concrete and visual representations, and recording the process symbolically; relating division to repeated subtraction; relating division to multiplication (Limited to division related to multiplication facts up to 5 × 5.)$txt$, $txt${"display_code":"Gr3 N12"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 3, $txt$N13$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of fractions by: explaining that a fraction represents a part of a whole; describing situations in which fractions are used; comparing fractions of the same whole with like denominators$txt$, $txt${"display_code":"Gr3 N13"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 3, $txt$PR01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of increasing patterns by describing, extending, comparing, and creating numerical (numbers to 1000) patterns and non-numerical patterns using manipulatives, diagrams, sounds, and actions.$txt$, $txt${"display_code":"Gr3 PR01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 14, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 3, $txt$PR02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of decreasing patterns by describing, extending, comparing, and creating numerical (numbers to 1000) patterns and non-numerical patterns using manipulatives, diagrams, sounds, and actions.$txt$, $txt${"display_code":"Gr3 PR02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 15, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 3, $txt$PR03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to solve one-step addition and subtraction equations involving symbols representing an unknown number.$txt$, $txt${"display_code":"Gr3 PR03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 16, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 3, $txt$M01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to relate the passage of time to common activities using standard units (minutes, hours, days, weeks, months, years).$txt$, $txt${"display_code":"Gr3 M01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 17, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 3, $txt$M02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to relate the number of seconds to a minute, the numbers of minutes to an hour, the numbers of hours to a day, and the number of days to a month in a problem-solving context.$txt$, $txt${"display_code":"Gr3 M02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 18, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 3, $txt$M03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of measuring length (cm, m) by selecting and justifying referents for the units centimetre or metre (cm, m); modelling and describing the relationship between the units centimetre or metre (cm, m); estimating length using referents; measuring and recording length, width, and height$txt$, $txt${"display_code":"Gr3 M03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 19, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 3, $txt$M04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of measuring mass (g, kg) by selecting and justifying referents for the units gram and kilogram (g, kg); modelling and describing the relationship between the units gram and kilogram (g, kg); estimating mass using referents; measuring and recording mass$txt$, $txt${"display_code":"Gr3 M04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 20, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 3, $txt$M05$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of perimeter of regular, irregular, and composite shapes by estimating perimeter using referents for centimetre or metre (cm, m); measuring and recording perimeter (cm, m); create different shapes for a given perimeter (cm, m) to demonstrate that many shapes are possible for a perimeter$txt$, $txt${"display_code":"Gr3 M05"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 21, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 3, $txt$G01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to describe 3-D objects according to the shape of the faces.$txt$, $txt${"display_code":"Gr3 G01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 22, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 3, $txt$G02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to name, describe, compare, create, and sort regular and irregular polygons, including triangles, quadrilaterals, pentagons, hexagons, and octagons according to the number of sides.$txt$, $txt${"display_code":"Gr3 G02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 23, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$SP$txt$), 3, $txt$SP01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to collect first-hand data and organize it using tally marks, line plots, charts, and lists to answer questions.$txt$, $txt${"display_code":"Gr3 SP01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 24, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$SP$txt$), 3, $txt$SP02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to construct, label, and interpret bar graphs to solve problems.$txt$, $txt${"display_code":"Gr3 SP02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%203%20Outcomes%20%282022%29.pdf$txt$, 25, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 4, $txt$N01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to represent and partition whole numbers to 10 000.$txt$, $txt${"display_code":"Gr4 N01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 4, $txt$N02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to compare and order numbers to 10 000.$txt$, $txt${"display_code":"Gr4 N02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 4, $txt$N03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of addition and subtraction of numbers with answers to 10 000 (limited to three-and four-digit numerals) by: using personal strategies for adding and subtracting; estimating sums and differences; solving problems involving addition and subtraction$txt$, $txt${"display_code":"Gr4 N03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 4, $txt$N04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to apply and explain the properties of 0 and 1 for multiplication and the property of 1 for division.$txt$, $txt${"display_code":"Gr4 N04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 4, $txt$N05$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to describe and apply mental mathematics strategies, to recall basic multiplication facts to 9 × 9, and to determine related division facts.$txt$, $txt${"display_code":"Gr4 N05"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 4, $txt$N06$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of multiplication (one-, two-, or three-digit by one-digit numerals) to solve problems: using personal strategies for multiplication, with and without concrete materials; using arrays to represent multiplication; connecting concrete representations to symbolic representations; estimating products; applying the distributive property$txt$, $txt${"display_code":"Gr4 N06"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 4, $txt$N07$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of division (one-digit divisor and up to two-digit dividend) to solve problems by: using personal strategies for dividing, with and without concrete materials; estimating quotients; relating division to multiplication$txt$, $txt${"display_code":"Gr4 N07"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 4, $txt$N08$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of fractions less than or equal to 1 by using concrete, pictorial, and symbolic representations to: name and record fractions for the parts of one whole or a set; compare and order fractions; model and explain that for different wholes, two identical fractions may not represent the same quantity; provide examples of where fractions are used$txt$, $txt${"display_code":"Gr4 N08"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 4, $txt$N09$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to describe and represent decimals (tenths and hundredths) concretely, pictorially, and symbolically.$txt$, $txt${"display_code":"Gr4 N09"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 4, $txt$N10$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to relate decimals to fractions and fractions to decimals (to hundredths).$txt$, $txt${"display_code":"Gr4 N10"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 4, $txt$N11$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of addition and subtraction of decimals (limited to hundredths) by estimating sums and differences; using mental mathematics strategies to solve problems; using personal strategies to determine sums and differences$txt$, $txt${"display_code":"Gr4 N11"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 4, $txt$PR01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to identify and describe patterns found in tables and charts, including a multiplication chart.$txt$, $txt${"display_code":"Gr4 PR01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 4, $txt$PR02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to translate among different representations of a pattern (a table, a chart, or concrete materials).$txt$, $txt${"display_code":"Gr4 PR02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 4, $txt$PR03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to represent, describe, and extend patterns and relationships, using charts and tables, to solve problems.$txt$, $txt${"display_code":"Gr4 PR03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 14, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 4, $txt$PR04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to identify and explain mathematical relationships, using charts and diagrams, to solve problems.$txt$, $txt${"display_code":"Gr4 PR04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 15, false, $txt$2026-10-17$txt$::date);
insert into public.standard (doc_id, strand_id, grade, code, code_type, source_system_id, level, parent_id, text, extra, source_url, display_order, needs_review, last_verified)
