  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 4, $txt$PR05$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to express a given problem as an equation in which a symbol is used to represent an unknown number.$txt$, $txt${"display_code":"Gr4 PR05"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 16, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 4, $txt$PR06$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to solve one-step equations involving a symbol to represent an unknown number.$txt$, $txt${"display_code":"Gr4 PR06"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 17, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 4, $txt$M01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to read and record time using digital and analog clocks, including 24-hour clocks.$txt$, $txt${"display_code":"Gr4 M01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 18, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 4, $txt$M03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of area of regular and irregular 2-D shapes by: recognizing that area is measured in square units; selecting and justifying referents for the units square centimetre (cm2 ) or square metre (m2); estimating area using referents for cm2 or m2; determining and recording area (cm2 or m2); constructing different rectangles for a given area (cm2 or m2) in order to demonstrate that many different rectangles may have the same area$txt$, $txt${"display_code":"Gr4 M03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 19, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 4, $txt$G01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to describe and construct rectangular and triangular prisms.$txt$, $txt${"display_code":"Gr4 G01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 20, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 4, $txt$G03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of line symmetry by: identifying symmetrical 2-D shapes; creating symmetrical 2-D shapes; drawing one or more lines of symmetry in a 2-D shape$txt$, $txt${"display_code":"Gr4 G03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 21, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$SP$txt$), 4, $txt$SP01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of many-to-one correspondence.$txt$, $txt${"display_code":"Gr4 SP01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 22, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$SP$txt$), 4, $txt$SP02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to construct and interpret pictographs and bar graphs involving many-to-one correspondence to draw conclusions.$txt$, $txt${"display_code":"Gr4 SP02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%204%20Outcomes%20%282022%29.pdf$txt$, 23, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 5, $txt$N01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to represent and partition whole numbers to 1 000 000.$txt$, $txt${"display_code":"Gr5 N01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 5, $txt$N02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to use estimation strategies, including front-end, front-end adjusted, rounding, and compatible numbers in problem-solving contexts.$txt$, $txt${"display_code":"Gr5 N02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 5, $txt$N03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to describe and apply mental mathematics strategies and number properties to recall, with fluency, answers for basic multiplication facts to 81 and related division facts.$txt$, $txt${"display_code":"Gr5 N03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 5, $txt$N04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to apply mental mathematics strategies for multiplication, including multiplying by multiples of 10, 100, and 1000; halving and doubling; using the distributive property$txt$, $txt${"display_code":"Gr5 N04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 5, $txt$N05$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate, with and without concrete materials, an understanding of multiplication (two-digit by two-digit) to solve problems.$txt$, $txt${"display_code":"Gr5 N05"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 5, $txt$N06$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate, with and without concrete materials, an understanding of division (three-digit by one-digit), and interpret remainders to solve problems.$txt$, $txt${"display_code":"Gr5 N06"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 5, $txt$N07$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of fractions by using concrete, pictorial, and symbolic representations to create sets of equivalent fractions; compare and order fractions with like and unlike denominators$txt$, $txt${"display_code":"Gr5 N07"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 5, $txt$N08$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to describe and represent decimals (tenths, hundredths, and thousandths) concretely, pictorially, and symbolically.$txt$, $txt${"display_code":"Gr5 N08"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 5, $txt$N09$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to relate decimals to fractions and fractions to decimals (to thousandths).$txt$, $txt${"display_code":"Gr5 N09"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 5, $txt$N10$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to compare and order decimals (to thousandths) by using benchmarks, place value, and equivalent decimals.$txt$, $txt${"display_code":"Gr5 N10"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 5, $txt$N11$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of addition and subtraction of decimals (limited to thousandths).$txt$, $txt${"display_code":"Gr5 N11"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 5, $txt$PR01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to determine the pattern rule to make predictions about subsequent terms.$txt$, $txt${"display_code":"Gr5 PR01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 5, $txt$PR02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to solve problems involving single-variable, one-step equations with whole number coefficients and whole number solutions.$txt$, $txt${"display_code":"Gr5 PR02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 5, $txt$M01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to design and construct different rectangles, given a perimeter or an area or both (whole numbers), and make generalizations.$txt$, $txt${"display_code":"Gr5 M01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 14, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 5, $txt$M02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of measuring length (mm) by selecting and justifying referents for the unit millimetre (mm); modelling and describing the relationship between millimetre (mm) and centimetre (cm) units, and between millimetre (mm) and metre (m) units$txt$, $txt${"display_code":"Gr5 M02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 15, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 5, $txt$M03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of volume by selecting and justifying referents for cubic centimetre (cm3) or cubic metre (m3) units; estimating volume using referents for cubic centimetre (cm3) or cubic metre (m3); measuring and recording volume (cm3 or m3); constructing rectangular prisms for a given volume$txt$, $txt${"display_code":"Gr5 M03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 16, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 5, $txt$M04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of capacity by describing the relationship between millilitre (mL) and litre (L) units; selecting and justifying referents for millilitre (mL) and litre (L) units; estimating capacity using referents for millilitre (mL) and litre (L); measuring and recording capacity (mL or L)$txt$, $txt${"display_code":"Gr5 M04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 17, false, $txt$2026-10-17$txt$::date),
