  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 5, $txt$G03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to perform a single transformation (translation, rotation, or reflection) of a 2-D shape (with and without technology) and draw and describe the image.$txt$, $txt${"display_code":"Gr5 G03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%205%20Outcomes%20%282022%29.pdf$txt$, 19, false, $txt$2026-10-17$txt$::date),
