  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 7, $txt$G02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to identify and plot points in the four quadrants of a Cartesian plane, using integral ordered pairs.$txt$, $txt${"display_code":"Gr7 G02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%207%20Outcomes%20%282022%29.pdf$txt$, 17, false, $txt$2026-10-17$txt$::date),
