  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$SP$txt$), 7, $txt$SP02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to determine the effect on the mean, median, and mode when an outlier is included in a data set.$txt$, $txt${"display_code":"Gr7 SP02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%207%20Outcomes%20%282022%29.pdf$txt$, 19, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$SP$txt$), 7, $txt$SP03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to construct, label, and interpret circle graphs to solve problems$txt$, $txt${"display_code":"Gr7 SP03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%207%20Outcomes%20%282022%29.pdf$txt$, 20, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$SP$txt$), 7, $txt$SP04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to express probabilities as ratios, fractions, and percents.$txt$, $txt${"display_code":"Gr7 SP04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%207%20Outcomes%20%282022%29.pdf$txt$, 21, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$SP$txt$), 7, $txt$SP06$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to conduct a probability experiment to compare the theoretical probability (determined using a tree diagram, table, or other graphic organizer) and experimental probability of two independent events.$txt$, $txt${"display_code":"Gr7 SP06"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%207%20Outcomes%20%282022%29.pdf$txt$, 22, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 8, $txt$N01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of perfect squares and square roots, concretely, pictorially, and symbolically (limited to whole numbers).$txt$, $txt${"display_code":"Gr8 N01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 8, $txt$N02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to determine the approximate square root of numbers that are not perfect squares (limited to whole numbers).$txt$, $txt${"display_code":"Gr8 N02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 2, false, $txt$2026-10-17$txt$::date);
