  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 8, $txt$N05$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to solve problems that involve rates, ratios, and proportional reasoning.$txt$, $txt${"display_code":"Gr8 N05"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 8, $txt$N06$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of multiplying and dividing positive fractions and mixed numbers, concretely, pictorially, and symbolically.$txt$, $txt${"display_code":"Gr8 N06"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$N$txt$), 8, $txt$N07$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to demonstrate an understanding of multiplication and division of integers, concretely, pictorially, and symbolically.$txt$, $txt${"display_code":"Gr8 N07"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 8, $txt$PR01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to graph and analyze two-variable linear relations.$txt$, $txt${"display_code":"Gr8 PR01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$PR$txt$), 8, $txt$PR02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to model and solve problems, concretely, pictorially, and symbolically, where a, b, and c are integers, using linear equations of the form ax = b; x/a = b, a ≠ 0; ax + b = c; x/a + b = c, a ≠ 0; a(x + b) = c$txt$, $txt${"display_code":"Gr8 PR02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 8, $txt$M01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to develop and apply the Pythagorean theorem to solve problems.$txt$, $txt${"display_code":"Gr8 M01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 8, $txt$M02$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to draw and construct nets for 3-D objects.$txt$, $txt${"display_code":"Gr8 M02"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 8, $txt$M03$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to determine the surface area of right rectangular prisms, right triangular prisms, and right cylinders to solve problems.$txt$, $txt${"display_code":"Gr8 M03"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 12, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$M$txt$), 8, $txt$M04$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to develop and apply formulas for determining the volume of right rectangular prisms, right triangular prisms, and right cylinders.$txt$, $txt${"display_code":"Gr8 M04"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 13, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$G$txt$), 8, $txt$G01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to draw and interpret top, front, and side views of 3-D objects composed of right rectangular prisms.$txt$, $txt${"display_code":"Gr8 G01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 14, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$NS-MATH-2022$txt$) and code = $txt$SP$txt$), 8, $txt$SP01$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Students will be expected to critique ways in which data is presented.$txt$, $txt${"display_code":"Gr8 SP01"}$txt$::jsonb, $txt$https://curriculum.novascotia.ca/sites/default/files/documents/outcomes-indicators-files/Mathematics%208%20Outcomes%20%282022%29.pdf$txt$, 15, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$) and code = $txt$N$txt$), 1, $txt$1.N1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Say the number sequence, 0 to 100, by 1s forward and backward between any two given numbers; 2s to 20, forward starting at 0; and 5s and 10s to 100, forward starting at 0.$txt$, $txt${}$txt$::jsonb, $txt$https://www.princeedwardisland.ca/sites/default/files/publications/eelc_math_1.pdf$txt$, 1, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$) and code = $txt$N$txt$), 1, $txt$1.N2$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Recognize, at a glance, and name familiar arrangements of 1 to 10 objects or dots.$txt$, $txt${}$txt$::jsonb, $txt$https://www.princeedwardisland.ca/sites/default/files/publications/eelc_math_1.pdf$txt$, 2, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$) and code = $txt$N$txt$), 1, $txt$1.N3$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of counting by indicating that the last number said identifies “how many”; showing that any set has only one count; using the counting on strategy; and using parts or equal groups to count sets.$txt$, $txt${}$txt$::jsonb, $txt$https://www.princeedwardisland.ca/sites/default/files/publications/eelc_math_1.pdf$txt$, 3, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$) and code = $txt$N$txt$), 1, $txt$1.N4$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Represent and describe numbers to 20 concretely, pictorially and symbolically.$txt$, $txt${}$txt$::jsonb, $txt$https://www.princeedwardisland.ca/sites/default/files/publications/eelc_math_1.pdf$txt$, 4, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$) and code = $txt$N$txt$), 1, $txt$1.N5$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Compare sets containing up to 20 elements to solve problems using: referents; and one-to-one correspondence.$txt$, $txt${}$txt$::jsonb, $txt$https://www.princeedwardisland.ca/sites/default/files/publications/eelc_math_1.pdf$txt$, 5, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$) and code = $txt$N$txt$), 1, $txt$1.N6$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate, concretely and pictorially, how a given number can be represented by a variety of equal groups with and without singles.$txt$, $txt${}$txt$::jsonb, $txt$https://www.princeedwardisland.ca/sites/default/files/publications/eelc_math_1.pdf$txt$, 6, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$) and code = $txt$N$txt$), 1, $txt$1.N7$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Identify the number, up to 20, that is one more, two more, one less and two less than a given number.$txt$, $txt${}$txt$::jsonb, $txt$https://www.princeedwardisland.ca/sites/default/files/publications/eelc_math_1.pdf$txt$, 7, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$) and code = $txt$N$txt$), 1, $txt$1.N8$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of addition of numbers with answers to 20 and their corresponding subtraction facts, concretely, pictorially and symbolically by: using familiar and mathematical language to describe additive and subtractive actions from their experience; creating and solving problems in context that involve addition and subtraction; and modelling addition and subtraction using a variety of concrete and visual representations, and recording the process symbolically.$txt$, $txt${}$txt$::jsonb, $txt$https://www.princeedwardisland.ca/sites/default/files/publications/eelc_math_1.pdf$txt$, 8, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$) and code = $txt$N$txt$), 1, $txt$1.N9$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Describe and use mental mathematics strategies (memorization not intended), such as: counting on and counting back; making 10; doubles; and using addition to subtract to determine the basic addition facts to 18 and related subtraction facts.$txt$, $txt${}$txt$::jsonb, $txt$https://www.princeedwardisland.ca/sites/default/files/publications/eelc_math_1.pdf$txt$, 9, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$) and code = $txt$PR$txt$), 1, $txt$1.PR1$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Demonstrate an understanding of repeating patterns (two to four elements) by: describing; reproducing; extending; and creating patterns using manipulatives, diagrams, sounds and actions.$txt$, $txt${}$txt$::jsonb, $txt$https://www.princeedwardisland.ca/sites/default/files/publications/eelc_math_1.pdf$txt$, 10, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$) and code = $txt$PR$txt$), 1, $txt$1.PR2$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Translate repeating patterns from one representation to another.$txt$, $txt${}$txt$::jsonb, $txt$https://www.princeedwardisland.ca/sites/default/files/publications/eelc_math_1.pdf$txt$, 11, false, $txt$2026-10-17$txt$::date),
  ((select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$), (select id from public.strand where doc_id = (select id from public.curriculum_doc where doc_key = $txt$PE-MATH-2024$txt$) and code = $txt$PR$txt$), 1, $txt$1.PR3$txt$, $txt$official$txt$, null, $txt$outcome$txt$, null, $txt$Describe equality as a balance and inequality as an imbalance, concretely and pictorially (0 to 20).$txt$, $txt${}$txt$::jsonb, $txt$https://www.princeedwardisland.ca/sites/default/files/publications/eelc_math_1.pdf$txt$, 12, false, $txt$2026-10-17$txt$::date),
